export type EventParametersItemSkew = { [key: string]: number };

/**
 * Cold-chain failure cascade. Liquid blood lots held by the failed assets are aged out / compromised by the simulator.
 */
export type EventParametersColdChain = {
  assetIds?: string[];
  assetTypes?: string[];
  outageHours?: number;
  initialCompromisedFraction?: number;
};

/**
 * Reagent / testing-supply shortage cascade. When gating reagents fall below thresholdDays at affected nodes, donor screening throughput collapses.
 */
export type EventParametersReagent = {
  reagentItemIds?: string[];
  thresholdDays?: number;
  minCapacityFraction?: number;
};

/**
 * Airlift loss cascade. Lengthens routes and degrades viability of arriving liquid blood lots.
 */
export type EventParametersAirlift = {
  additionalTransitDays?: number;
  viabilityLossPerDay?: number;
  affectedModalities?: string[];
};

export type EventParametersImpactedSuppliersItem = {
  supplierId: string;
  /** 0..1 multiplier on baseline capacity. 1 = unchanged. 0 = offline (skipped by the ranker). */
  capacityMultiplier?: number;
  /** Days added to the supplier's mean lead time during the outage window. */
  leadTimeDeltaDays?: number;
  /** Delta on reliability score (e.g. -0.3 drops a 0.9 supplier to 0.6). */
  reliabilityDelta?: number;
  /** Days inside the scenario horizon the supplier is degraded. Defaults to the full horizon. */
  outageDays?: number;
  /** Human-friendly cause surfaced in the UI / AI brief. */
  cause?: string;
  /** True when the entry was auto-suggested by the country auto-flag pass (not authored by the operator). */
  autoFlagged?: boolean;
};

/**
 * Perturbation parameters applied by the simulation engine.
 */
export interface EventParameters {
  affectedNodes?: string[];
  /** Operator-drawn theater zone IDs. The runner expands these into affected nodes (any node inside any referenced zone) and applies route delays/reliability hits to routes crossing them. */
  zoneIds?: string[];
  encounterMultiplier?: number;
  populationMultiplier?: number;
  wasteMultiplier?: number;
  routeReliabilityDelta?: number;
  routeDelayDays?: number;
  specimensMultiplier?: number;
  itemSkew?: EventParametersItemSkew;
  /** Cold-chain failure cascade. Liquid blood lots held by the failed assets are aged out / compromised by the simulator. */
  coldChain?: EventParametersColdChain;
  /** Reagent / testing-supply shortage cascade. When gating reagents fall below thresholdDays at affected nodes, donor screening throughput collapses. */
  reagent?: EventParametersReagent;
  /** Airlift loss cascade. Lengthens routes and degrades viability of arriving liquid blood lots. */
  airlift?: EventParametersAirlift;
  /** Per-supplier degradation knobs. The runner blends each entry over the scenario horizon and feeds the degraded values into the COA supplier ranker. */
  impactedSuppliers?: EventParametersImpactedSuppliersItem[];
}

