export const TagAutoTagInputScope = {
  recent: "recent",
  untagged: "untagged",
} as const;

export interface TagAutoTagInput {
  entityType: TagEntityType;
  scope: TagAutoTagInputScope;
  /** @maximum 25 */
  limit?: number;
}

export type TagSource = (typeof TagSource)[keyof typeof TagSource];

export const TagSource = {
  manual: "manual",
  ai: "ai",
} as const;

export interface Tag {
  id: string;
  name: string;
  slug: string;
  color: string;
  description: string;
  source: TagSource;
  createdAt: string;
  updatedAt: string;
}

export type TagSummary = Tag & {
  usageCount: number;
};

export type TagCreateInputSource =
  (typeof TagCreateInputSource)[keyof typeof TagCreateInputSource];

export const TagCreateInputSource = {
  manual: "manual",
  ai: "ai",
} as const;

export interface TagCreateInput {
  name: string;
  color?: string;
  description?: string;
  source?: TagCreateInputSource;
}

export interface TagUpdateInput {
  name?: string;
  color?: string;
  description?: string;
}

export type TagAssignmentViewAppliedBy =
  (typeof TagAssignmentViewAppliedBy)[keyof typeof TagAssignmentViewAppliedBy];

export const TagAssignmentViewAppliedBy = {
  manual: "manual",
  ai: "ai",
} as const;

export interface TagAssignmentView {
  id: number;
  tagId: string;
  tag: Tag;
  entityType: TagEntityType;
  entityId: string;
  appliedBy: TagAssignmentViewAppliedBy;
  appliedByActor?: string;
  /** @nullable */
  aiModel?: string | null;
  /** @nullable */
  aiProvider?: string | null;
  /** @nullable */
  rationale?: string | null;
  createdAt: string;
}

export type TagDetailEntityRefAppliedBy =
  (typeof TagDetailEntityRefAppliedBy)[keyof typeof TagDetailEntityRefAppliedBy];

export const TagDetailEntityRefAppliedBy = {
  manual: "manual",
  ai: "ai",
} as const;

export interface TagDetailEntityRef {
  entityType: TagEntityType;
  entityId: string;
  label: string;
  /** @nullable */
  sublabel?: string | null;
  /** @nullable */
  deeplink?: string | null;
  appliedBy?: TagDetailEntityRefAppliedBy;
  /** @nullable */
  rationale?: string | null;
  createdAt?: string;
}

export type TagDetailByEntityTypeItem = {
  entityType: TagEntityType;
  entries: TagDetailEntityRef[];
};

export interface TagDetail {
  tag: Tag;
  usageCount: number;
  byEntityType: TagDetailByEntityTypeItem[];
}

export interface TagSuggestion {
  name: string;
  /** @nullable */
  slug?: string | null;
  /** @nullable */
  color?: string | null;
  isNew: boolean;
  rationale: string;
  confidence: number;
}

export interface TagSuggestionResponse {
  generatedAt: string;
  provider: string;
  model: string;
  suggestions: TagSuggestion[];
}

export type AutoTagBatchResultResultsItem = {
  entityId: string;
  label: string;
  applied: string[];
  /** @nullable */
  error?: string | null;
};

export interface AutoTagBatchResult {
  generatedAt: string;
  provider: string;
  model: string;
  processed: number;
  applied: number;
  results: AutoTagBatchResultResultsItem[];
}

export type PatientTypeRequirementsItem = {
  itemId: string;
  quantityPerPatient: number;
  notes: string;
};

export interface PatientType {
  id: string;
  name: string;
  severity: string;
  careCategory: string;
  avgClinicianMinutes: number;
  description: string;
  requirements: PatientTypeRequirementsItem[];
}

export type EventTypeDefaultPatientMixItem = {
  patientTypeId: string;
  defaultShare: number;
};

export interface EventType {
  id: string;
  name: string;
  category: string;
  description: string;
  defaultArrivalWindowHours: number;
  defaultPatientMix: EventTypeDefaultPatientMixItem[];
}

/**
 * Patient counts keyed by patient_type id.
 */
export type CasualtyEvaluateInputPatientCounts = { [key: string]: number };

export interface CasualtyEvaluateInput {
  /**
   * Optional. When set, scopes the response to a specific site (adds sufficiency rows + reroute suggestions).
   * @nullable
   */
  siteId?: string | null;
  /** Patient counts keyed by patient_type id. */
  patientCounts: CasualtyEvaluateInputPatientCounts;
  /** Hours over which the casualty load arrives. */
  arrivalWindowHours: number;
  /**
   * Optional operator-entered ETA for next resupply.
   * @nullable
   */
  resupplyEtaHours?: number | null;
  restrictReroutesToHub?: boolean;
}

export type CasualtyRequirementRowSource =
  (typeof CasualtyRequirementRowSource)[keyof typeof CasualtyRequirementRowSource];

export const CasualtyRequirementRowSource = {
  patient_bom: "patient_bom",
  ppe_staffing: "ppe_staffing",
  both: "both",
} as const;

export interface CasualtyRequirementRow {
  itemId: string;
  itemName: string;
  category: string;
  classOfSupply: string;
  unitOfIssue: string;
  commodityType: string;
  unspscCommodity: string;
  size: string;
  productNoun: string;
  requiredQty: number;
  source: CasualtyRequirementRowSource;
}

export interface SupplierAlternative {
  supplierId: string;
  supplierName: string;
  channel: string;
  country: string;
  projectedEta: number;
  score: number;
  reliabilityScore?: number;
  leadTimeDaysMean?: number;
  /** @nullable */
  rationale?: string | null;
}

export type SufficiencyRowVerdict =
  (typeof SufficiencyRowVerdict)[keyof typeof SufficiencyRowVerdict];

export const SufficiencyRowVerdict = {
  green: "green",
  amber: "amber",
  red: "red",
} as const;

export type SufficiencyRow = CasualtyRequirementRow & {
  onHand: number;
  inboundBeforeWindow: number;
  shortfallQty: number;
  verdict: SufficiencyRowVerdict;
  supplierAlternatives?: SupplierAlternative[];
};

export interface SufficiencySummary {
  totalRequiredItems: number;
  greenCount: number;
  amberCount: number;
  redCount: number;
  verdict: string;
}

export type PatientRerouteCandidatePosture =
  (typeof PatientRerouteCandidatePosture)[keyof typeof PatientRerouteCandidatePosture];

export const PatientRerouteCandidatePosture = {
  viable: "viable",
  stretched: "stretched",
  unsuitable: "unsuitable",
} as const;

export interface PatientRerouteCandidate {
  nodeId: string;
  nodeName: string;
  /** @nullable */
  countryCode?: string | null;
  distanceKm: number;
  estimatedTransitDays: number;
  posture: PatientRerouteCandidatePosture;
  supplyCoverage: number;
  residualCapacity: number;
  rationale: string;
}

export type CasualtyEvaluateResultPatientCounts = { [key: string]: number };

export type CasualtyEvaluateResultSufficiency = null | {
  rows: SufficiencyRow[];
  summary: SufficiencySummary;
};

export interface CasualtyEvaluateResult {
  arrivalWindowHours: number;
  totalPatients: number;
  patientCounts: CasualtyEvaluateResultPatientCounts;
  requiredItems: CasualtyRequirementRow[];
  sufficiency?: CasualtyEvaluateResultSufficiency;
  reroutes: PatientRerouteCandidate[];
}

